import type { Path, Row } from "./types";

/**
 * Split cache. Bounded on purpose — the previous implementation used an unbounded module-level
 * `Map`, which in a long-lived app grows for every distinct path string it ever sees. Paths come
 * from a fixed field config in practice, so a small cap costs nothing and removes the leak.
 */
const CACHE_LIMIT = 512;
const cache = new Map<string, string[]>();

function split(path: Path): string[] {
  const hit = cache.get(path);
  if (hit) return hit;
  const parts = path.split(".");
  if (cache.size >= CACHE_LIMIT) cache.clear();
  cache.set(path, parts);
  return parts;
}

/** Read a dotted path off a row. Returns `undefined` for any missing link in the chain. */
export function getByPath(obj: unknown, path: Path | undefined | null): unknown {
  if (obj == null || path == null || path === "") return undefined;
  if (typeof obj !== "object") return undefined;
  let cur: unknown = obj;
  for (const key of split(path)) {
    if (cur == null) return undefined;
    cur = (cur as Record<string, unknown>)[key];
  }
  return cur;
}

/** Read a path and coerce to string for display/compare. `undefined`/`null` become `""`. */
export function getString(obj: unknown, path: Path | undefined | null): string {
  const v = getByPath(obj, path);
  return v == null ? "" : String(v);
}

/** `"created_at"` / `"createdAt"` → `"Created At"`. Uses the last segment of a dotted path. */
export function formatPathLabel(path: Path): string {
  if (!path) return "";
  const tail = path.includes(".") ? path.split(".").pop()! : path;

  if (tail.includes("_")) {
    return tail
      .split("_")
      .filter(Boolean)
      .map((w) => w.charAt(0).toUpperCase() + w.slice(1))
      .join(" ");
  }

  return tail
    .replace(/([A-Z])/g, " $1")
    .replace(/^./, (s) => s.toUpperCase())
    .trim();
}

/**
 * The default row identity: the first of `row.id`, `row._id`, `row.uuid`, else the array index.
 *
 * The previous implementation fell back through three candidates ending in the array index, so
 * selection and drag-and-drop both broke the moment rows were reordered. Pass `getRowId` when
 * your id lives elsewhere.
 */
export function defaultGetRowId(row: Row, index: number): string {
  const id = row.id ?? row._id ?? row.uuid;
  return id == null ? String(index) : String(id);
}

import type { DataViewsQuery, FilterState, Sort } from "./types";

/**
 * The wire format for a `DataViewsQuery`, both directions.
 *
 * A query is written in the browser and read on the server, and the two have to agree exactly.
 * Keeping the encoder and the decoder in one file is what makes that true by construction —
 * split across a page and a route handler, they drift the first time either side gains a field.
 *
 * No React here, like its neighbours `path.ts` and `types.ts`, so a route handler can import it.
 */

/** A query nobody has touched yet: everything, first page. */
export function emptyQuery(overrides?: Partial<DataViewsQuery>): DataViewsQuery {
  return { search: "", filters: {}, sort: null, page: 1, pageSize: 10, ...overrides };
}

/**
 * Browser → wire.
 *
 * `filters` goes as JSON because it is a nested structure, not a flat list of values. `sort` goes
 * as `total:desc` — one parameter rather than two, since neither half means anything alone.
 *
 * Extra parameters an endpoint of your own needs are yours to append:
 *
 * ```ts
 * const params = queryToParams(query);
 * params.set("shape", "wide");
 * ```
 */
export function queryToParams(query: DataViewsQuery): URLSearchParams {
  return new URLSearchParams({
    search: query.search,
    filters: JSON.stringify(query.filters),
    sort: query.sort ? `${query.sort.path}:${query.sort.direction}` : "",
    page: String(query.page),
    pageSize: String(query.pageSize),
  });
}

/**
 * Wire → server.
 *
 * Malformed `filters` is treated as "no filters" rather than a 400: a filter you cannot parse
 * should not take the page down. `pageSize` is clamped, because it arrives from the client and a
 * request for a million rows is a request to fall over.
 */
export function parseQuery(url: URL): DataViewsQuery {
  const params = url.searchParams;

  let filters: FilterState = {};
  const raw = params.get("filters");
  if (raw) {
    try {
      filters = JSON.parse(raw) as FilterState;
    } catch {
      filters = {};
    }
  }

  const [sortPath, sortDir] = (params.get("sort") ?? "").split(":");
  const sort: Sort = sortPath
    ? { path: sortPath, direction: sortDir === "desc" ? "desc" : "asc" }
    : null;

  return {
    search: params.get("search") ?? "",
    filters,
    sort,
    page: Math.max(1, Number(params.get("page")) || 1),
    pageSize: Math.min(500, Math.max(1, Number(params.get("pageSize")) || 10)),
  };
}

/**
 * The vocabulary DataViews speaks — nothing more.
 *
 * DataViews does no data work: it never filters, searches, sorts, groups, or infers a schema.
 * Those are the app's job, almost always server-side. What is described here is only what the
 * component needs in order to **paint** rows and to **emit intent** back to you:
 * `FilterState` and `Sort` are things it hands you so you can go and query, not things it applies.
 *
 * These types live in the utils layer so the dependency runs one way — the component imports its
 * vocabulary from here, and nothing here imports React or any component.
 */

import type { ReactNode } from "react";

/** A row is any record. DataViews never assumes a shape beyond the id resolved by `getRowId`. */
export type Row = Record<string, unknown>;

/** A dotted accessor into a row, e.g. `"customer.name"`. */
export type Path = string;

export type FieldType =
  | "text"
  | "number"
  | "date"
  | "boolean"
  | "hidden"
  | "enum-badge"
  | "badge-array"
  | "currency"
  | "number-format"
  | "progress-bar"
  | "star-rating"
  | "icon-text"
  | "two-line"
  | "avatar"
  | "link"
  | "image"
  | "date-format";

export type BadgeVariant =
  | "green"
  | "greenLight"
  | "cocktailGreen"
  | "yellow"
  | "redOrange"
  | "redLight"
  | "rose"
  | "purple"
  | "bluePurple"
  | "blue"
  | "navy"
  | "gray"
  | "highlight";

/** Palette keys for a board column pill. */
export type ColumnColor = "gray" | "purple" | "orange" | "blue" | "green" | "red";

export type CurrencyOptions = {
  symbol?: string;
  locale?: string;
  decimals?: number;
  code?: string;
};

/** How one field is read and painted. You author these — nothing is inferred from the data. */
export type FieldConfig = {
  path: Path;
  label?: string;
  type?: FieldType;
  visible?: boolean;

  /** Value → badge colour, for `enum-badge` / `badge-array`. */
  variants?: Record<string, BadgeVariant>;
  defaultVariant?: BadgeVariant;
  variant?: BadgeVariant;

  limit?: number;
  currency?: string | CurrencyOptions;
  format?: Intl.NumberFormatOptions;
  thresholds?: [number, number];
  max?: number;
  icon?: string;
  iconPosition?: "before" | "after";
  secondaryPath?: Path;
  linkType?: "mailto" | "tel" | "url";
  fallbackPath?: Path;
  dateFormat?: string | Intl.DateTimeFormatOptions;
  trueLabel?: string;
  falseLabel?: string;
  trueVariant?: BadgeVariant;
  falseVariant?: BadgeVariant;

  /** Paint this field yourself. Wins over `type`. */
  render?: (value: unknown, row: Row) => ReactNode;
};

/** A column as the user has arranged it — the projection the config panel edits. */
export type ColumnState = {
  path: Path;
  label: string;
  visible: boolean;
};

type SortDirection = "asc" | "desc";
/** Which column the header shows as sorted. Emitted on click; the component never re-orders rows. */
export type Sort = { path: Path; direction: SortDirection } | null;

type NumericRange = { kind: "number"; min?: number; max?: number };
type DateRange = { kind: "date"; from?: string; to?: string };
type RangeValue = NumericRange | DateRange;
/** A categorical selection, or a range. */
export type FilterValue = string[] | RangeValue;
/** Keyed by field path. */
export type FilterState = Record<Path, FilterValue>;

/** A one-click shortcut on a numeric filter, e.g. "Under 500". */
export type NumberPreset = { label: string; min?: number; max?: number };
/** A one-click shortcut on a date filter, e.g. "Last 30 days". */
export type DatePreset = { label: string; from?: string; to?: string };
/** `Filters.Presets` takes both shapes; each control renders the ones it understands. */
export type Preset = NumberPreset | DatePreset;

/**
 * Everything the user asked for, in one object.
 *
 * This is the whole contract between `DataViews` and your data layer. The component collects it —
 * a search typed in the header, filters set in the rail, a column header clicked, a page turned —
 * and hands it over whole; going and fetching the matching rows is your half.
 *
 * It is one object rather than five callbacks because it is one question. A query with a new
 * filter and a stale page number is not a query anyone meant to ask, and keeping the parts
 * together is what lets the component keep them consistent — changing a filter resets `page` to 1,
 * because a different result set has no page 4 to stay on.
 */
export interface DataViewsQuery {
  search: string;
  filters: FilterState;
  sort: Sort;
  /** 1-based. */
  page: number;
  pageSize: number;
}

/** How a filter maps between its control's value and `FilterState`. */
type FilterKind = "choice" | "number" | "date" | "text";

/**
 * What `DataViews.Filters` learned about one of its children.
 *
 * You never write these: filters are authored as `FormBuilder` fields, and `Filters` reads each
 * child's `name`, `label` and bounds off the element to build this. It exists because the mapping
 * to `FilterState` needs to know a slider from a multi-select — a `[0, 500]` is a numeric range,
 * while `["a", "b"]` is a selection, and the two are indistinguishable once they are just values.
 */
export type FilterFieldDescriptor = {
  path: Path;
  label?: string;
  kind: FilterKind;
  /** Single-valued choice (`FormBuilder.Select`) rather than multi (`.MultiSelect`). */
  single?: boolean;
  /** Slider bounds, read from the child. A slider resting on them emits no filter at all. */
  min?: number;
  max?: number;
};

export type TreeNode = {
  id: string;
  row: Row;
  children: TreeNode[];
  depth: number;
};

/** Emitted by a board or tree drag. The component never applies it. */
export type MoveIntent = {
  id: string;
  from: string | null;
  to: string | null;
  index?: number;
};

/** A pre-grouped column for the board view. You build these; the component only paints them. */
export type RowGroup = {
  id: string;
  label: string;
  color?: ColumnColor;
  rows: Row[];
};
